332	        if (settings.terms() != null) {
333	            dated(settings, store, today, Settings.TERMS, settings.terms());
334	        }
335	        settings.gradeTerms().forEach((grade, days) -> dated(settings, store, today, Settings.gradeTermsKey(grade), days));
336	        if (settings.latePct() != null) {
337	            dated(settings, store, today, Settings.LATE_PCT, settings.latePct());
338	        }
339	        if (settings.policyDate() != null) {
340	            store.set(settings.sheetId(), Settings.POLICY_DATE, settings.policyDate());
341	        }
342	        if (settings.periodNumberingFrom() != null) {
343	            store.set(settings.sheetId(), Settings.PERIOD_NUMBERING_FROM, settings.periodNumberingFrom());
344	        }
345	        if (settings.cap() != null) {
346	            dated(settings, store, today, Settings.CAP, settings.cap());
347	        }
348	        if (settings.proofThreshold() != null) {
349	            dated(settings, store, today, Settings.PROOF_THRESHOLD, settings.proofThreshold());
350	        }
351	        settings.gradeProof().forEach((grade, amount) -> dated(settings, store, today, Settings.gradeProofKey(grade), amount));
352	        if (settings.noteThreshold() != null) {
353	            dated(settings, store, today, Settings.NOTE_THRESHOLD, settings.noteThreshold());
354	        }
355	        if (settings.graceDays() != null) {
356	            store.set(settings.sheetId(), Settings.GRACE_DAYS, settings.graceDays());
357	        }
358	        settings.gradeGrace().forEach((grade, days) -> dated(settings, store, today, Settings.gradeGraceKey(grade), days));
359	        if (settings.entryDate() != null) {
360	            store.set(settings.sheetId(), Settings.ENTRY_DATE, settings.entryDate());
361	        }
362	        settings.perms().forEach((action, roles) -> store.set(settings.sheetId(), Settings.permKey(action), roles));
363	        if (settings.pot() != null) {
364	            store.set(settings.sheetId(), Settings.POT, settings.pot());
365	        }
366	        if (settings.parent() != null) {
367	            store.set(settings.sheetId(), Settings.PARENT, settings.parent());
368	        }
369	    }
